import {freshState,escapeHTML as h} from './model.js?v=0.31.0';
import {curiosity} from './content.js?v=0.31.0';
import {availableFamilies,createExplorationPlan,personalPlanExport} from './guide-state.js?v=0.31.0';
import {explorationSnapshot} from './exploration-plan.js?v=0.31.0';
export const uncertaintyExamples=[
 {id:'mixed',title:'Mixed interests',themes:{R:2,I:4,A:5,S:4,E:2,C:3},overrides:{8:3,14:5,20:3},fields:['creative','health'],confidence:3,priorities:['creativity','impact','variety'],project:'Made a biology infographic for a school project.',reflection:'I like visual ideas and understanding how people stay healthy. I want room for both.',expectation:'Several directions stay open. The student chooses creative work and health as things to try, without choosing a profession.'},
 {id:'low-confidence',title:'Low confidence',themes:{R:2,I:4,A:3,S:5,E:2,C:3},overrides:{8:3,14:5,20:3},fields:['health'],confidence:1,priorities:['impact','curiosity'],project:'Helped explain a science topic to a younger student.',reflection:'Helping people interests me, but I have hardly tried this and do not feel confident yet.',expectation:'Health remains an interest connection. Low confidence leads to a smaller, supported first activity; it does not rule out a career.'},
 {id:'not-sure',title:'Mostly not sure',unknown:true,overrides:{3:4,9:5,27:4},fields:[],confidence:null,priorities:['variety'],project:'I am still looking for something I want to try.',reflection:'I have not tried enough to choose a direction.',expectation:'Three creative likes are kept as clues. With 27 unfamiliar answers, no field or profession is recommended.'}
];
export function uncertaintyState(id){const e=uncertaintyExamples.find(x=>x.id===id)||uncertaintyExamples[0],s=freshState();for(const q of curiosity)s.curiosity[q.id]=e.overrides[Number(q.id.split('-')[1])]??(e.unknown?'untried':e.themes[q.theme]);s.priorities=[...e.priorities];if(Number.isInteger(e.confidence))for(const id of ['data','making','communication','investigation'])s.confidence[id]={exposure:'new',confidence:e.confidence};else s.skippedModules.push('confidence');s.evidence.project=e.project;s.reflection.energy=e.reflection;Object.assign(s.guide,{entry:'assessment',familyIds:[...e.fields],family:e.fields[0]||''});createExplorationPlan(s);return s;}
export function uncertaintyResult(id){const state=uncertaintyState(id);return {state,status:explorationSnapshot(state),fields:availableFamilies(state).filter(f=>f.connection.supported).slice(0,3),plan:personalPlanExport(state)};}
export function uncertaintyExamplesPage(id='mixed'){const e=uncertaintyExamples.find(x=>x.id===id)||uncertaintyExamples[0],{state,status,fields}=uncertaintyResult(e.id);return `<div class="page-intro"><div><span class="eyebrow">THREE FICTIONAL STUDENT WALKTHROUGHS</span><h1>There’s room to be unsure.</h1><p>Read-only examples. Your answers and saved plan stay yours.</p></div></div><nav class="uncertainty-example-tabs" aria-label="Exploration examples">${uncertaintyExamples.map(x=>`<a href="#/student-examples/${x.id}" ${e.id===x.id?'aria-current="page"':''}>${x.title}</a>`).join('')}</nav><section class="guide-input-panel"><h2>What this student says</h2><p>${h(e.reflection)}</p><p><strong>${h(e.expectation)}</strong></p>${fields.length?'<h3>Optional fields worth exploring</h3><div class="tags">'+fields.map(f=>'<span class="tag">'+h(f.title)+'</span>').join('')+'</div><p>A starting point for exploration. No profession is assigned.</p>':'<p><strong>No field recommendation yet.</strong> Not sure stays unknown; it does not become a low score.</p>'}</section><details class="more-info"><summary>The exact answers and checks</summary><div><p>Original reflection prompts, not a validated aptitude test. ${status.answered} rated activities. ${status.unknown} unfamiliar activities. No measured ability score.</p><p>${e.confidence===null?'Confidence was skipped. No confidence or ability level is inferred.':'All four confidence responses: '+e.confidence+'/5, with little or no experience.'} Confidence, money, and education preferences do not lower interest connections.</p>${curiosity.map(q=>`<p><strong>${state.curiosity[q.id]==='untried'?'Not sure':state.curiosity[q.id]+'/5'}</strong> · ${h(q.text)}</p>`).join('')}<p>The questionnaire now continues directly to career fields. Uncertain answers do not assign a profession. Earlier activity notes and steps remain saved. All-unknown, all-neutral, all-high, all-low, skipped sections, and earlier saved careers also have regression checks. These are usability and consistency checks, not evidence of predictive validity.</p></div></details><p><a href="#/student-examples/next-step">After trying the activities: see a student choose a career →</a></p><p><a href="#/student-examples/medicine">See the four career-focused examples →</a></p>`;}
